import sys
if sys.version_info < (3, 10):
    from importlib_metadata import entry_points
else:
    from importlib.metadata import entry_points

from .exceptions import GetFactoryInstanceFailed, GetProviderInstanceFailed


class EntryPoint:

    _FACTORIES_DICT = {}
    _PROVIDERS_DICT = {}

    def __init__(self):
        self._FACTORIES_DICT = self._FACTORIES_DICT if self._FACTORIES_DICT \
            else self.__load_entrypoints("config_model_v1.factory")

        self._PROVIDERS_DICT = self._PROVIDERS_DICT if self._PROVIDERS_DICT \
            else self.__load_entrypoints("config_model_v1.provider")

    def __load_entrypoints(self, group_name):
        return {
            entry_point.name: entry_point.load()
            for entry_point in entry_points().select(group=group_name)
        }

    def get_factory_instance(self, type_name):
        if type_name not in self._FACTORIES_DICT:
            raise GetFactoryInstanceFailed(type_name)
        return self._FACTORIES_DICT[type_name]()

    def get_provider_instance(self, type_name):
        if type_name not in self._PROVIDERS_DICT:
            raise GetProviderInstanceFailed(type_name)
        return self._PROVIDERS_DICT[type_name]()
